// 演示 1：在有序数组 [10, 20, 30, 50, 60] 中插入 25。
// 25 应该位于 20 和 30 之间，也就是下标 2；为了腾出这个位置，30、50、60 都要向右移动。
let arr = [10, 20, 30, 50, 60];
let insertVal = 25;
let targetIndex = 2; // 明确记录目标位置，避免把“业务位置”和“循环下标”混在一起。
let shiftCount = 0; // 用计数器观察这次插入实际搬动了多少个元素。

// 连续数组不能在中间凭空增加空位，所以先扩展数组，再从最后往前搬。
// 从后往前是关键：如果从前往后复制，原来的 30 会被新值覆盖，后面就再也找不回来了。
arr.push(undefined);
for (let i = arr.length - 1; i > targetIndex; i--) {
  arr[i] = arr[i - 1]; // 例如先把 60 搬到 5，再把 50 搬到 4，保证每个原值都有临时落脚点。
  shiftCount++;
}
arr[targetIndex] = insertVal; // 现在下标 2 已经空出来，25 才能安全写入。

console.log("插入后数组:", arr);
console.log("被迫平移搬迁的内存块数量:", shiftCount, "次");
console.log("------------------------------------------");

// 演示 2：让哈希函数直接计算槽位。
// 这里不遍历整个数组，而是把 Key 的每个字符逐步混入 hash，最后得到可以直接访问的下标。
function simpleHash(key, capacity = 10) {
  let hash = 0; // 从 0 开始累积，表示目前还没有读取任何字符。
  for (let i = 0; i < key.length; i++) {
    // 乘以 31 是为了让新字符影响已有结果，再加上字符编码，最后取模限制槽位范围。
    hash = (hash * 31 + key.charCodeAt(i)) % capacity;
  }
  return hash; // 返回 0 到 capacity-1 之间的槽位编号，而不是返回一个无法直接使用的大整数。
}

console.log("Key 'Alice' 直接算出的槽位号:", simpleHash('Alice'));
console.log("Key 'Bob'   直接算出的槽位号:", simpleHash('Bob'));

